import{_ as s,o as e,c as i,a2 as t}from"./chunks/framework.BXzK3EA4.js";const n="/rpi_gpu_boot.png",g=JSON.parse('{"title":"Day 5: Raspberry Pi Hardware Bring-Up","description":"","frontmatter":{},"headers":[],"relativePath":"day5-raspberry-pi-hardware-bringup.md","filePath":"day5-raspberry-pi-hardware-bringup.md"}'),r={name:"day5-raspberry-pi-hardware-bringup.md"};function o(l,a,p,h,d,c){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="day-5-raspberry-pi-hardware-bring-up" tabindex="-1">Day 5: Raspberry Pi Hardware Bring-Up <a class="header-anchor" href="#day-5-raspberry-pi-hardware-bring-up" aria-label="Permalink to &quot;Day 5: Raspberry Pi Hardware Bring-Up&quot;">​</a></h1><div style="background:linear-gradient(135deg, #11998e 0%, #38ef7d 100%);padding:1.5rem;border-radius:12px;margin-bottom:2rem;color:white;"><p><strong>🎯 Learning Objectives</strong></p><p>By the end of this module, you will be able to:</p><ol><li>Explain the unique Broadcom VideoCore GPU-first boot sequence of the Raspberry Pi</li><li>Integrate the <code>meta-raspberrypi</code> BSP layer into a Yocto build</li><li>Configure <code>local.conf</code> to build for <code>raspberrypi3</code> or <code>raspberrypi4</code></li><li>Flash the resulting image to an SD card (or run it under QEMU emulation)</li><li>Connect to the serial console via UART GPIO pins</li></ol></div><div class="info custom-block"><p class="custom-block-title">PREREQUISITES</p><ul><li>Completed <a href="/day4-yocto-releases-bsp-layers-wic.html">Day 4: Yocto Releases, BSP Layers &amp; WIC</a></li><li>A Raspberry Pi 3 or 4 (Optional) or QEMU</li></ul></div><hr><h2 id="_1-the-unique-raspberry-pi-boot-sequence" tabindex="-1">1. The Unique Raspberry Pi Boot Sequence <a class="header-anchor" href="#_1-the-unique-raspberry-pi-boot-sequence" aria-label="Permalink to &quot;1. The Unique Raspberry Pi Boot Sequence&quot;">​</a></h2><p>Unlike the BeagleBone Black (or most other ARM SoCs) where the ARM CPU wakes up first and runs a bootloader like U-Boot, the Raspberry Pi&#39;s Broadcom SoC (System on Chip) relies on its <strong>VideoCore GPU</strong> to orchestrate the boot sequence.</p><p>The ARM CPU is held in reset while the GPU initializes the system.</p><p><img src="'+n+`" alt="Raspberry Pi GPU Boot Sequence"></p><ol><li><strong>Stage 1 (Boot ROM):</strong> The GPU wakes up and executes immutable code baked into the SoC. It mounts the FAT32 partition on the SD card.</li><li><strong>Stage 2 (<code>bootcode.bin</code>):</strong> The GPU loads this firmware file from the SD card. It enables the SDRAM (memory).</li><li><strong>Stage 3 (<code>start.elf</code>):</strong> The GPU loads this core firmware. It reads <code>config.txt</code> (the Raspberry Pi equivalent of BIOS settings), configures the hardware (clocks, HDMI, GPIO), loads the Device Tree Blob (DTB), and finally loads the Linux Kernel (<code>kernel.img</code>) into RAM.</li><li><strong>Stage 4 (Linux Kernel):</strong> The GPU releases the ARM CPU from reset, pointing it to the loaded kernel. Linux boots.</li></ol><div class="warning custom-block"><p class="custom-block-title">NO U-BOOT REQUIRED</p><p>By default, the Raspberry Pi skips U-Boot entirely! The GPU firmware (<code>start.elf</code>) directly loads the Linux Kernel. While it is possible to configure <code>start.elf</code> to load U-Boot instead (which then loads Linux), the standard Yocto <code>meta-raspberrypi</code> configuration follows the direct-boot approach.</p></div><hr><h2 id="_2-building-yocto-for-the-raspberry-pi" tabindex="-1">2. Building Yocto for the Raspberry Pi <a class="header-anchor" href="#_2-building-yocto-for-the-raspberry-pi" aria-label="Permalink to &quot;2. Building Yocto for the Raspberry Pi&quot;">​</a></h2><p>The official BSP layer for all Raspberry Pi models is <code>meta-raspberrypi</code>.</p><h3 id="step-1-clone-the-layer" tabindex="-1">Step 1: Clone the Layer <a class="header-anchor" href="#step-1-clone-the-layer" aria-label="Permalink to &quot;Step 1: Clone the Layer&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/poky</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Ensure the branch matches your Poky installation!</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kirkstone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git://git.yoctoproject.org/meta-raspberrypi</span></span></code></pre></div><h3 id="step-2-add-to-bblayers-conf" tabindex="-1">Step 2: Add to <code>bblayers.conf</code> <a class="header-anchor" href="#step-2-add-to-bblayers-conf" aria-label="Permalink to &quot;Step 2: Add to \`bblayers.conf\`&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bitbake-layers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add-layer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../meta-raspberrypi</span></span></code></pre></div><h3 id="step-3-configure-local-conf" tabindex="-1">Step 3: Configure <code>local.conf</code> <a class="header-anchor" href="#step-3-configure-local-conf" aria-label="Permalink to &quot;Step 3: Configure \`local.conf\`&quot;">​</a></h3><p>Edit your <code>conf/local.conf</code> to target the specific Pi model.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># For Raspberry Pi 3 (32-bit):</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MACHINE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;raspberrypi3&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># For Raspberry Pi 3 (64-bit):</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># MACHINE = &quot;raspberrypi3-64&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># For Raspberry Pi 4 (64-bit):</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># MACHINE = &quot;raspberrypi4-64&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Enable UART serial console (crucial for headless debugging!)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ENABLE_UART</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;1&quot;</span></span></code></pre></div><h3 id="step-4-build-the-image" tabindex="-1">Step 4: Build the Image <a class="header-anchor" href="#step-4-build-the-image" aria-label="Permalink to &quot;Step 4: Build the Image&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bitbake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> core-image-minimal</span></span></code></pre></div><hr><h2 id="_3-emulating-raspberry-pi-with-qemu-no-hardware-required" tabindex="-1">3. Emulating Raspberry Pi with QEMU (No Hardware Required!) <a class="header-anchor" href="#_3-emulating-raspberry-pi-with-qemu-no-hardware-required" aria-label="Permalink to &quot;3. Emulating Raspberry Pi with QEMU (No Hardware Required!)&quot;">​</a></h2><p>If you don&#39;t have a physical Raspberry Pi, you can still boot your compiled Yocto image using QEMU. QEMU natively supports the <code>raspi3b</code> machine model.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Navigate to the deploy directory</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tmp/deploy/images/raspberrypi3</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Extract the rootfs if it&#39;s compressed</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># (assuming IMAGE_FSTYPES includes ext3 or ext4)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run QEMU specifying the raspi3b machine, your kernel, DTB, and rootfs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">qemu-system-aarch64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -M</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> raspi3b</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -cpu</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cortex-a53</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1G</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -kernel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zImage</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -dtb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bcm2710-rpi-3-b.dtb</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -drive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> format=raw,file=core-image-minimal-raspberrypi3.ext3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -append</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;rw earlyprintk loglevel=8 console=ttyAMA0,115200 dwc_otg.lpm_enable=0 root=/dev/mmcblk0 rootwait&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -no-reboot</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -serial</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stdio</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -nographic</span></span></code></pre></div><hr><h2 id="_4-hardware-bring-up-physical-board" tabindex="-1">4. Hardware Bring-Up (Physical Board) <a class="header-anchor" href="#_4-hardware-bring-up-physical-board" aria-label="Permalink to &quot;4. Hardware Bring-Up (Physical Board)&quot;">​</a></h2><p>If you have the physical hardware, use the <code>.wic</code> image generated by BitBake.</p><h3 id="_4-1-flashing-the-sd-card" tabindex="-1">4.1 Flashing the SD Card <a class="header-anchor" href="#_4-1-flashing-the-sd-card" aria-label="Permalink to &quot;4.1 Flashing the SD Card&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># WARNING: Identify the correct /dev/sdX for your SD card</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> if=tmp/deploy/images/raspberrypi3/core-image-minimal-raspberrypi3.wic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> of=/dev/sdX</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bs=4M</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status=progress</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sync</span></span></code></pre></div><h3 id="_4-2-uart-serial-console-connection" tabindex="-1">4.2 UART Serial Console Connection <a class="header-anchor" href="#_4-2-uart-serial-console-connection" aria-label="Permalink to &quot;4.2 UART Serial Console Connection&quot;">​</a></h3><p>Since <code>core-image-minimal</code> lacks SSH and video drivers, you must connect via the UART serial console.</p><p><strong>Wiring the FTDI USB-to-Serial Cable:</strong></p><ol><li>Connect FTDI <strong>GND</strong> (Black) to Pi <strong>Pin 6 (GND)</strong></li><li>Connect FTDI <strong>TX</strong> (Green) to Pi <strong>Pin 10 (RXD)</strong></li><li>Connect FTDI <strong>RX</strong> (White) to Pi <strong>Pin 8 (TXD)</strong></li><li><em>Do NOT connect the VCC (Red) wire if the Pi is powered via USB-C/Micro-USB!</em></li></ol><p><strong>Connecting via Terminal:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> picocom</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 115200</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/ttyUSB0</span></span></code></pre></div><p>Power on the Raspberry Pi. You should see the kernel log followed by a login prompt. Login as <code>root</code> (no password).</p><hr><h2 id="_5-hands-on-lab-exercises" tabindex="-1">5. Hands-On Lab Exercises <a class="header-anchor" href="#_5-hands-on-lab-exercises" aria-label="Permalink to &quot;5. Hands-On Lab Exercises&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">LAB 5.1: Analyzing the Boot Partition</p><p>Mount the flashed SD card (or inspect the <code>boot</code> directory in <code>tmp/deploy/images/raspberrypi3/</code>) on your host machine.</p><ol><li>Locate <code>bootcode.bin</code> and <code>start.elf</code> (the closed-source Broadcom firmware).</li><li>Open <code>config.txt</code>. Notice how BitBake automatically populated <code>enable_uart=1</code> because you set <code>ENABLE_UART = &quot;1&quot;</code> in <code>local.conf</code>.</li><li>Locate the <code>kernel.img</code> (or <code>kernel7.img</code>/<code>kernel8.img</code> depending on architecture) and the <code>bcm27xx.dtb</code> Device Tree files.</li></ol></div><hr><h2 id="_6-further-reading" tabindex="-1">6. Further Reading <a class="header-anchor" href="#_6-further-reading" aria-label="Permalink to &quot;6. Further Reading&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>URL</th></tr></thead><tbody><tr><td>meta-raspberrypi Documentation</td><td><a href="https://meta-raspberrypi.readthedocs.io/" target="_blank" rel="noreferrer">meta-raspberrypi.readthedocs.io</a></td></tr><tr><td>Raspberry Pi Boot Sequence</td><td><a href="https://www.raspberrypi.com/documentation/computers/raspberry-pi.html#boot-sequence" target="_blank" rel="noreferrer">raspberrypi.com/documentation/computers/raspberry-pi.html#boot-sequence</a></td></tr></tbody></table><hr><div style="display:flex;justify-content:space-between;margin-top:2rem;padding-top:1rem;border-top:1px solid #e2e8f0;"><a href="/day4-yocto-releases-bsp-layers-wic">← Day 4: Releases, BSP Layers &amp; WIC</a><a href="/day6-bitbake-operators-and-layer-creation">Day 6: BitBake Operators &amp; Layers →</a></div>`,46)])])}const b=s(r,[["render",o]]);export{g as __pageData,b as default};
